#!/usr/bin/env node
// generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
//
// Общее у parallel-tests.mjs и mutants.mjs: слоты машины, запуск процессов с гашением
// своих по своим PID, подстановки шаблонов настроек tests. Модуль, не команда.
//
// Слоты — общие на машину, а не на сессию: тесты упираются в задержку базы и сервисов,
// и все прогоны всех сессий машины делят одно число процессов. Захват — файл slot-<номер>
// с PID владельца в общем каталоге; номер слота уникален среди одновременных прогонов,
// поэтому база или копия дерева с номером в имени не пересекается с соседней сессией.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';

export class UserError extends Error {}
export const say = (s) => process.stdout.write(s + '\n');
export const fail = (msg) => { throw new UserError(msg); };

// Не os.tmpdir(): временный каталог процесса переопределяют песочница сессии и сами
// инструменты для воркеров, а семафор обязан быть одним для всех сессий машины.
export const SLOTS_DIR = process.env.BEERPOWERS_TEST_SLOTS_DIR
  || (process.platform === 'win32'
    ? path.join(process.env.LOCALAPPDATA ? path.join(process.env.LOCALAPPDATA, 'Temp') : os.tmpdir(), 'beerpowers-test-slots')
    : path.join('/tmp', `beerpowers-test-slots-${typeof process.getuid === 'function' ? process.getuid() : 'user'}`));
const LOCK_STALE_MS = 10_000;
const mine = new Set();

// Лимит: личная переменная машины → tests.slots проекта → число логических ядер.
export function slotLimit(ws) {
  const own = process.env.BEERPOWERS_TEST_SLOTS;
  if (own) {
    const n = Number(own);
    if (!Number.isInteger(n) || n < 1) fail(`BEERPOWERS_TEST_SLOTS=${own} — ждётся целое больше нуля`);
    return { n, from: 'BEERPOWERS_TEST_SLOTS' };
  }
  if (ws.tests.slots) return { n: ws.tests.slots, from: 'tests.slots' };
  return { n: os.availableParallelism(), from: 'число ядер' };
}

const alive = (pid) => {
  try { process.kill(pid, 0); return true; } catch (e) { return e.code === 'EPERM'; }
};

// Осмотр и захват идут под замком-каталогом: без него два прогона, увидев один протухший
// захват, оба сочли бы слот своим.
export async function locked(fn) {
  fs.mkdirSync(SLOTS_DIR, { recursive: true });
  const lock = path.join(SLOTS_DIR, '.lock');
  for (;;) {
    try { fs.mkdirSync(lock); break; } catch (e) {
      if (e.code !== 'EEXIST') throw e;
      try {
        if (Date.now() - fs.statSync(lock).mtimeMs > LOCK_STALE_MS) { fs.rmdirSync(lock); continue; }
      } catch { /* замок сняли между проверками */ }
      await sleep(25);
    }
  }
  try { return fn(); } finally { try { fs.rmdirSync(lock); } catch { /* уже снят */ } }
}

export function scan({ clean }) {
  const held = new Map();
  let names = [];
  try { names = fs.readdirSync(SLOTS_DIR); } catch { return held; }
  for (const f of names) {
    const m = f.match(/^slot-(\d+)$/);
    if (!m) continue;
    const p = path.join(SLOTS_DIR, f);
    let c = null;
    try { c = JSON.parse(fs.readFileSync(p, 'utf8')); } catch { /* битый захват — протух */ }
    if (c && Number.isInteger(c.pid) && alive(c.pid)) { held.set(Number(m[1]), c); continue; }
    if (clean) {
      try { fs.unlinkSync(p); say(`STALE ${f} pid=${c?.pid ?? '?'} — процесс мёртв, захват убран`); } catch { /* убрал сосед */ }
    }
  }
  return held;
}

// Берёт min(want, свободно); свободных нет — ждёт, строкой WAIT раз в минуту.
export async function acquire(want, limit, meta, label) {
  let waited = 0;
  for (;;) {
    const got = await locked(() => {
      const held = scan({ clean: true });
      const free = limit.n - held.size;
      if (free <= 0) return { busy: held.size };
      const ids = [];
      for (let s = 1; ids.length < Math.min(want, free); s++) {
        if (held.has(s)) continue;
        const claim = { pid: process.pid, ...meta, since: new Date().toISOString() };
        try {
          fs.writeFileSync(path.join(SLOTS_DIR, `slot-${s}`), JSON.stringify(claim), { flag: 'wx' });
        } catch (e) {
          if (e.code === 'EEXIST') continue; // протухший захват не удалось убрать — слот пропускается
          throw e;
        }
        mine.add(s);
        ids.push(s);
      }
      return { ids };
    });
    if (got.ids) return got.ids;
    if (waited % 60 === 0) say(`WAIT ${label}: свободных слотов нет — заняты ${got.busy} из ${limit.n} (${limit.from}), жду${waited ? ` ${waited} с` : ''}`);
    await sleep(1000);
    waited++;
  }
}

export function release(ids) {
  for (const s of ids) {
    const p = path.join(SLOTS_DIR, `slot-${s}`);
    try {
      if (JSON.parse(fs.readFileSync(p, 'utf8')).pid === process.pid) fs.unlinkSync(p);
    } catch { /* захвата уже нет */ }
    mine.delete(s);
  }
}

// ---------- процессы ----------

const children = new Set();

const killTree = (c) => {
  if (!c.pid) return;
  if (process.platform === 'win32') spawnSync('taskkill', ['/pid', String(c.pid), '/T', '/F'], { stdio: 'ignore', windowsHide: true });
  else { try { process.kill(-c.pid, 'SIGTERM'); } catch { /* группа уже вышла */ } }
};

export function killChildren() {
  for (const c of children) killTree(c);
}

// Остановленный инструмент гасит свои процессы и снимает свои захваты.
export function installStopHandlers() {
  process.on('exit', () => release([...mine]));
  for (const sig of ['SIGINT', 'SIGTERM', 'SIGHUP']) {
    process.on(sig, () => {
      say(`STOP ${sig}: гашу воркеры по своим PID`);
      killChildren();
      release([...mine]);
      say('CODE=130');
      process.exit(130);
    });
  }
}

export const TIMEOUT_CODE = 124;

// Команда — в оболочке системы (cmd.exe на Windows, sh на остальных), вывод — в открытый
// файл log. По таймауту дерево процесса гасится, код — TIMEOUT_CODE.
export function run(command, { cwd, env, log, timeoutMs, tool }) {
  fs.writeSync(log, `\n$ ${command}\n`);
  return new Promise((resolve) => {
    let child;
    try {
      // detached на POSIX — своя группа процессов: так гасится и всё, что запустила оболочка.
      child = spawn(command, { cwd, env, shell: true, stdio: ['ignore', log, log], windowsHide: true, detached: process.platform !== 'win32' });
    } catch (e) {
      fs.writeSync(log, `${tool}: запуск не удался: ${e.message}\n`);
      resolve(127);
      return;
    }
    children.add(child);
    let timedOut = false;
    const timer = timeoutMs ? setTimeout(() => { timedOut = true; killTree(child); }, timeoutMs) : null;
    child.on('error', (e) => { fs.writeSync(log, `${tool}: запуск не удался: ${e.message}\n`); });
    child.on('close', (code, signal) => {
      if (timer) clearTimeout(timer);
      children.delete(child);
      fs.writeSync(log, timedOut ? `\n# таймаут ${timeoutMs / 1000} с — дерево процесса погашено\n` : `\n# код выхода ${code ?? signal}\n`);
      resolve(timedOut ? TIMEOUT_CODE : code ?? 1);
    });
  });
}

// ---------- подстановки ----------

export function subst(s, vars) {
  return s.replace(/\{([a-z]+)(?::([A-Za-z_][A-Za-z0-9_]*))?\}/g, (m, name, arg) => {
    if (name === 'env') {
      const v = process.env[arg];
      if (v === undefined) fail(`переменная окружения ${arg} не задана — личное значение машины кладут в env файла .claude/settings.local.json`);
      return v;
    }
    return name in vars ? String(vars[name]) : m;
  });
}

export const quote = (f) => (/[\s"&|<>^()%!;]/.test(f) ? `"${f}"` : f);
